mapper.select:
select signal_id, signal_type, agent_code, account_code, target_type, target_id, task_id, cast(detail as text) as detail, source,
       create_by, create_time
from abr_growth_signal

    and signal_type = #{signalType}
    and agent_code = #{agentCode}
    and source = #{source}

        and create_time >= cast(#{params.beginTime} as date)


        and create_time < cast(#{params.endTime} as date) + interval '1 day'


order by signal_id desc

select coalesce(agent_code, '') as "agentCode", count(*) as "count" from abr_growth_signal
where signal_type = #{signalType} and create_time >= #{since}
group by coalesce(agent_code, '')
